const path = require('path');
const { test, expect } = require('@playwright/test');
const flow = require('../utils/flow');
const { LoginPage } = require('../pages/LoginPage');
const { InventoryPage } = require('../pages/InventoryPage');
const { GoldBarcodePage } = require('../pages/GoldBarcodePage');
const { SafePage } = require('../pages/SafePage');

// Packs ONE loan's collateral using the barcode generated by `npm run barcode` (test-data/last-barcode.json)
// and stores it in the vault/safe created by `npm run vault` + `npm run safe` (test-data/last-safe.json).
// Override locker: $env:LOCKER_NO=3
test('TC_INVENTORY_001 - Inventory Form: bind generated barcode to the loan packet and store in vault/safe/locker', async ({ page }, testInfo) => {
  const inv = new InventoryPage(page);
  const barcode = GoldBarcodePage.readHandOff();
  const safe = SafePage.readHandOff();
  if (!barcode?.barcode) console.log('SKIPPED: no BH barcode hand-off – run: npm run barcode');
  test.skip(!barcode?.barcode, 'No barcode hand-off – run: npm run barcode');
  if (!safe?.safeNo) console.log('SKIPPED: no safe hand-off – run: npm run vault → npm run safe');
  test.skip(!safe?.safeNo, 'No safe hand-off – run: npm run vault; npm run safe');
  if (barcode?.status === 'Used') console.log(`SKIPPED: barcode ${barcode.barcode} (loan ${barcode.loanNumber}) was already used in the Inventory Form${barcode.safeNo ? ` → ${barcode.vaultName} / ${barcode.safeNo} / locker ${barcode.locker}` : ''}. A barcode is one-time – run: npm run token → npm run barcode → npm run inventory`);
  test.skip(barcode?.status === 'Used', `Barcode ${barcode?.barcode} was already used in the Inventory Form – generate a new one: npm run token; npm run barcode`);
  const flowLoan = flow.need('loanNumber', 'token');
  expect(barcode.loanNumber, `BH barcode ${barcode.barcode} belongs to ${barcode.loanNumber}, not the flow loan ${flowLoan} – run: npm run barcode`).toBe(flowLoan);
  console.log(`Using barcode ${barcode.barcode} for loan ${barcode.loanNumber} (${barcode.customer}); vault ${safe.vaultName}, safe ${safe.safeNo}`);
  testInfo.annotations.push({ type: 'test-data', description: `${barcode.loanNumber} → ${barcode.barcode} → ${safe.vaultName} / ${safe.safeNo}` });

  await test.step('Login as admin', () => new LoginPage(page).login('CHECKER_BH'));
  await test.step('Open Loans → Gold → Inventory Form', () => inv.open());

  await test.step(`Loan Type = Gold Loan, Loan = ${barcode.loanNumber}`, async () => {
    await inv.selectLoan(barcode.loanNumber);
    const info = await inv.customerInfo();
    console.log('Customer:', JSON.stringify(info), '| Collateral:', (await inv.collateral()).join(' || '));
    expect(info.customer).toMatch(new RegExp(barcode.customer, 'i'));
  });

  await test.step(`Scan barcode ${barcode.barcode} → Bind to Packet No`, () => inv.bindBarcode(barcode.barcode));

  let stored;
  await test.step('Packet photo, Vault / Safe / Locker → Add', async () => {
    stored = await inv.storeIn({
      photo: path.resolve(__dirname, '../test-data/gold-article.png'),
      vaultName: safe.vaultName,
      safeNo: safe.safeNo,
      lockerNo: process.env.LOCKER_NO,
    });
    console.log('Stored in:', JSON.stringify(stored));
    await inv.add.click();
    await expect(inv.collateralRows().filter({ hasText: barcode.barcode }).first()).toBeVisible();
    console.log('Collateral after Add:', (await inv.collateral()).join(' || '));
  });

  await test.step('Remarks → Save', async () => {
    await inv.remarks.fill(`Automation inventory ${barcode.barcode} → ${safe.vaultName}/${safe.safeNo}/L${stored.locker}`);
    // Let earlier toasts (e.g. "Barcode valid …") disappear so we read the Save result only
    await expect(page.locator('.toast-message')).toHaveCount(0, { timeout: 15_000 });
    await inv.save.click();
    const dialog = page.locator('.swal2-confirm:visible, .modal.show button:has-text("Yes"), .modal.show button:has-text("Confirm")').first();
    if (await dialog.isVisible({ timeout: 2000 }).catch(() => false)) await dialog.click();
    await expect(page.locator('.toast-message, .swal2-html-container').first()).toBeVisible();
    const msgs = (await inv.messages()).join(' ');
    console.log('Messages after save:', msgs);
    expect(msgs).toMatch(/success|saved/i);
    expect(msgs).not.toMatch(/error|fail|please|already/i);
  });

  await test.step('Mark barcode as used in the hand-off file', async () => {
    GoldBarcodePage.saveHandOff({ ...barcode, status: 'Used', usedIn: 'Inventory Form', vaultName: safe.vaultName, safeNo: safe.safeNo, locker: stored.locker });
    flow.update('inventory', { packedWith: barcode.barcode, vaultName: safe.vaultName, safeNo: safe.safeNo, locker: stored.locker });
  });
});
